public int LeastInterval(char[] tasks, int n)
{
    var counts = new int[26];
    foreach (char t in tasks) counts[t - 'A']++;

    int maxFreq = 0;
    foreach (int c in counts) maxFreq = Math.Max(maxFreq, c);

    // How many distinct tasks appear maxFreq times?
    int maxCount = 0;
    foreach (int c in counts)
    {
        if (c == maxFreq) maxCount++;
    }

    // Frames of size n + 1, one per gap, plus the final row
    int frameSize = (maxFreq - 1) * (n + 1) + maxCount;

    // If there are enough distinct tasks, no idle time is needed
    return Math.Max(frameSize, tasks.Length);
}

public int LeastIntervalHeap(char[] tasks, int n)
{
    var counts = new int[26];
    foreach (char t in tasks) counts[t - 'A']++;

    // Max-heap via negated priority
    var heap = new PriorityQueue<int, int>();
    foreach (int c in counts)
    {
        if (c > 0) heap.Enqueue(c, -c);
    }

    int time = 0;

    while (heap.Count > 0)
    {
        var batch = new List<int>();
        int slot = 0;

        // Take up to n + 1 distinct tasks in this round
        while (slot <= n && heap.Count > 0)
        {
            batch.Add(heap.Dequeue());
            slot++;
        }

        // Put back the ones with work remaining
        foreach (int remaining in batch)
        {
            if (remaining - 1 > 0)
            {
                heap.Enqueue(remaining - 1, -(remaining - 1));
            }
        }

        // If work remains, this round consumed n + 1 slots; otherwise only what we used
        time += heap.Count > 0 ? n + 1 : slot;
    }

    return time;
}

public int LeastInterval(char[] tasks, int n)
{
    var counts = new int[26];
    foreach (char t in tasks) counts[t - 'A']++;

    int maxFreq = 0;
    foreach (int c in counts) maxFreq = Math.Max(maxFreq, c);

    int maxCount = 0;
    foreach (int c in counts) if (c == maxFreq) maxCount++;

    return Math.Max((maxFreq - 1) * (n + 1) + maxCount, tasks.Length);
}
